{"name": "exec", "call_id": "call_b91318921ff64172a532afb2253167a7", "input": "text(await tools.apply_patch("*** Begin Patch\n*** Add File: [PROJECT_WORKSPACE]/output/refined-ui/board-test/test_apps.py\n+\"\"\"Real-board application entry, navigation and native-layout smoke checks.\"\"\"\n+from pathlib import Path\n+import json,re,time,serial,hashlib\n+\n+out=Path(__file__).resolve().parent\n+port=serial.Serial(port=None,baudrate=115200,timeout=.1,write_timeout=3)\n+port.dtr=False;port.rts=False;port.port='COM4';port.open()\n+log=(out/'apps-console.log').open('wb')\n+results=[]\n+\n+def command(text,timeout=16):\n+    port.reset_input_buffer()\n+    encoded=(text+'\\r').encode('utf-8')\n+    for i in range(0,len(encoded),8):port.write(encoded[i:i+8]);time.sleep(.025)\n+    data=bytearray();deadline=time.monotonic()+timeout;received=time.monotonic()\n+    while time.monotonic()<deadline:\n+        chunk=port.read(max(1,port.in_waiting))\n+        if chunk:data.extend(chunk);received=time.monotonic()\n+        if b'nsh>' in data and time.monotonic()-received>.25:break\n+    log.write(b'\\nCOMMAND '+text.encode()+b'\\n'+data);log.flush()\n+    value=data.decode('utf-8',errors='replace').replace('\\r','')\n+    if b'nsh>' not in data:raise RuntimeError('console timeout: '+text)\n+    if re.search(r'Assertion|PANIC|Guru Meditation|Segmentation fault',value,re.I):raise RuntimeError('runtime fault')\n+    return value\n+\n+def audit(stem):\n+    value=command('desktop ui audit')\n+    match=re.search(r'UI_LAYOUT_BEGIN\\s*(\\[.*?\\])\\s*UI_LAYOUT_END',value,re.S)\n+    if not match:raise RuntimeError('native audit missing')\n+    tree=json.loads(match[1]);(out/(stem+'.json')).write_text(json.dumps(tree,ensure_ascii=False,indent=2),encoding='utf-8')\n+    labels=[r['text'] for r in tree if r['type']=='label' and r['text']]\n+    if len(labels)<2:raise RuntimeError('empty native page')\n+    return labels\n+\n+def check(name,open_command,actions=(),wait=1.2):\n+    record={'name':name,'open_command':open_command,'status':'failed'}\n+    try:\n+        command('desktop ui home');value=command(open_command);time.sleep(wait)\n+        if 'unknown UI page' in value:raise RuntimeError('entry missing')\n+        labels=audit(name);record['label_count']=len(labels)\n+        runtime=command('desktop ui qpk-capacity-status')\n+        error=re.search(r'qpk-resources widgets=(\\d+) error=(.*)',runtime)\n+        if error:\n+            record['native_widgets']=int(error[1]);record['runtime_error']=error[2].strip()\n+            if record['runtime_error']:raise RuntimeError(record['runtime_error'])\n+        record['actions']=[]\n+        for action in actions:\n+            reply=command('desktop ui '+action);time.sleep(.6)\n+            if action.startswith('click:') and '-> 0' in reply:raise RuntimeError('control not reachable: '+action)\n+            record['actions'].append(action)\n+        if actions:audit(name+'-after')\n+        command('desktop ui home');navigation=command('desktop ui navigation-status')\n+        if 'page=home' not in navigation:raise RuntimeError('return failed')\n+        record['status']='passed'\n+    except Exception as e:record['error']=str(e)\n+    results.append(record);save();print(name,record['status'],record.get('error',''),flush=True)\n+\n+def save():\n+    (out/'apps-results.json').write_text(json.dumps({'firmware_sha256':hashlib.sha256((out.parent/'nuttx-refined-ui.bin').read_bytes()).hexdigest(),'method':'real COM4 board; production application entries and native LVGL object audits','checks':results},ensure_ascii=False,indent=2),encoding='utf-8')\n+\n+try:\n+    command('');command('uname -a');command('free');command('ls /dev');command('mount')\n+    for page in ['home','settings','wifi','bluetooth','files','resources','weather','environment','portal','about','music','chat']:\n+        actions={'music':['music-status'],'chat':['chat-status'],'weather':['weather-status']}.get(page,[])\n+        check(page,'desktop ui '+page,actions)\n+    # Launch through the real registered Apps grid, including its second page.\n+    names=['网络直播','本地视频','ESPClaw AI 助手','相机','录音机','智能家居','蓝牙鼠标','Grok Ball','2048','你好快应用','ESP-DL 离线识别','大肥鱼桌宠']\n+    for index,name in enumerate(names):\n+        command('desktop ui apps');time.sleep(.4)\n+        if index>=9:command('desktop ui click:下一页');time.sleep(.4)\n+        labels=audit('registered-'+str(index))\n+        if not any(name in label for label in labels):\n+            results.append({'name':name,'status':'failed','error':'not registered in Apps grid'});save();continue\n+        # check() normally closes the previous page; reopen the Apps grid inside this step.\n+        reply=command('desktop ui click:'+name);time.sleep(2)\n+        record={'name':name,'status':'failed','registered':True}\n+        try:\n+            if '-> 1' not in reply:raise RuntimeError('registered button failed')\n+            record['label_count']=len(audit('app-'+str(index)))\n+            status=command('desktop ui qpk-capacity-status')\n+            error=re.search(r'qpk-resources widgets=(\\d+) error=(.*)',status)\n+            if error:\n+                record['native_widgets']=int(error[1]);record['runtime_error']=error[2].strip()\n+                if record['runtime_error']:raise RuntimeError(record['runtime_error'])\n+            navigation=command('desktop ui navigation-status');record['navigation']=re.search(r'navigation .+',navigation)[0]\n+            if 'page=apps' in navigation:raise RuntimeError('application never opened')\n+            if 'page=qapp' in navigation or 'page=chat' in navigation:\n+                command('desktop ui app-back');back=command('desktop ui navigation-status')\n+                if 'page=apps' not in back:raise RuntimeError('return to Apps failed')\n+            command('desktop ui home');record['status']='passed'\n+        except Exception as e:record['error']=str(e)\n+        results.append(record);save();print(name,record['status'],record.get('error',''),flush=True)\n+    command('desktop ui home');command('free');command('desktop cameras');command('desktop espdl');\n+finally:\n+    save();log.close();port.close()\n+print('BOARD_APPS_DONE',sum(r['status']=='passed' for r in results),'/',len(results),flush=True)\n*** End Patch"));
