{"name": "exec", "call_id": "call_ed6d83eeb51c4cfa8fc9369c67ace6ca", "input": "text(await tools.apply_patch("*** Begin Patch\n*** Add File: [PROJECT_WORKSPACE]/output/refined-ui/board-test/check_functions.py\n+from pathlib import Path\n+import serial,time,re,json,hashlib\n+out=Path(__file__).resolve().parent\n+s=serial.Serial(port=None,baudrate=115200,timeout=.1,write_timeout=3);s.dtr=False;s.rts=False;s.port='COM4';s.open()\n+log=(out/'functions-console.log').open('wb');checks=[]\n+def cmd(text,timeout=18):\n+    if text.startswith('desktop ui ') and ' ' in text[11:]:text='desktop ui \"'+text[11:]+'\"'\n+    s.reset_input_buffer();data=bytearray();encoded=(text+'\\r').encode()\n+    for i in range(0,len(encoded),8):s.write(encoded[i:i+8]);time.sleep(.025)\n+    end=time.monotonic()+timeout;last=time.monotonic()\n+    while time.monotonic()<end:\n+        b=s.read(max(1,s.in_waiting));data.extend(b)\n+        if b:last=time.monotonic()\n+        if b'nsh>' in data and time.monotonic()-last>.3:break\n+    log.write(b'\\nCOMMAND '+text.encode()+b'\\n'+data);log.flush()\n+    result=data.decode('utf-8',errors='replace')\n+    if b'nsh>' not in data:raise RuntimeError('No prompt: '+text)\n+    return result\n+def status():\n+    reply=cmd('desktop ui qpk-capacity-status')\n+    m=re.search(r'widgets=(\\d+) error=([^\\r\\n]*)',reply)\n+    if not m:raise RuntimeError('No runtime status')\n+    if m[2].strip() or int(m[1])==0:raise RuntimeError('runtime: '+m[2])\n+    return int(m[1])\n+def audit(name):\n+    reply=cmd('desktop ui audit');(out/(name+'.txt')).write_text(reply,encoding='utf-8')\n+    return reply\n+def click(label):\n+    r=cmd('desktop ui click:'+label)\n+    if '-> 1' not in r:raise RuntimeError('Unreachable '+label)\n+def run(name,fn):\n+    record={'name':name}\n+    try:record['evidence']=fn();record['status']='passed'\n+    except Exception as e:record.update(status='failed',error=str(e))\n+    checks.append(record);print(name,record['status'],record.get('error',''),flush=True)\n+    (out/'functions-results.json').write_text(json.dumps({'firmware_sha256':hashlib.sha256((out.parent/'nuttx-refined-ui.bin').read_bytes()).hexdigest(),'checks':checks},ensure_ascii=False,indent=2),encoding='utf-8')\n+def grok():\n+    cmd('desktop ui apps');click('Grok Ball');time.sleep(3);count=status();assert count>12\n+    audit('grok-board-live');click('思考');time.sleep(1);status();a=audit('grok-board-thinking');assert '思考' in a\n+    click('表情');time.sleep(.5);status();a=audit('grok-board-picker');assert '选择表情' in a\n+    click('关闭');time.sleep(.4);click('巡演');time.sleep(8);status();click('停止');time.sleep(.3);status()\n+    cmd('desktop ui app-back');r=cmd('desktop ui navigation-status');assert 'page=apps' in r\n+    return {'native_widgets':count,'controls':['思考','表情','关闭','巡演','停止'],'returned_to_apps':True}\n+def ha():\n+    cmd('desktop ui apps');click('智能家居');time.sleep(2);count=status();a=audit('ha-board-config')\n+    assert '固件未提供' not in a and 'Home Assistant 接口' not in a\n+    cmd('desktop ui app-back');assert 'page=apps' in cmd('desktop ui navigation-status')\n+    return {'native_widgets':count,'note':'native backend present; HA account is not configured'}\n+def audio():\n+    cmd('desktop ui home');r=cmd('desktop hardware-test audio',timeout=55)\n+    assert 'failures=0' in r and 'wav-metadata=PASS' in r\n+    return {'record_play_stop_cancel_wav_metadata':'passed','temporary_diagnostic_clips':'removed by diagnostic'}\n+def dl():\n+    cmd('desktop ui espdl');click('物体分类');time.sleep(.5);status();audit('espdl-board-classify')\n+    cmd('desktop ui espdl-photo');time.sleep(7);r=cmd('desktop espdl');audit('espdl-board-result')\n+    assert 'error=0' in r,'inference status: '+r\n+    cmd('desktop ui home');return {'classification_status':r}\n+try:\n+    cmd('');run('grok-live-controls',grok);run('ha-live-entry',ha);run('audio-roundtrip',audio);run('espdl-classification',dl)\n+    cmd('desktop ui home');cmd('free');cmd('mount');cmd('desktop ui weather-status');cmd('desktop ui chat-status')\n+finally:log.close();s.close()\n*** End Patch"));
