{"name": "exec", "call_id": "call_a531a8dcbc1d4f22ae871aad4256a8ec", "input": "text(await tools.apply_patch("*** Begin Patch\n*** Add File: [PROJECT_WORKSPACE]/project/ouo/grok_mosaic_draw.inc\n+/* SPDX-License-Identifier: Apache-2.0 */\n+/* Optional per-polygon 2 px raster grid, for the isolated mini preview. */\n+static uint32_t grok_mosaic_color(const struct qpk_polygon_s *p,int x,int y)\n+{\n+  if(!p->gradient.kind)return p->color;\n+  lv_color_t c=qpk_polygon_color(p,x+1,y+1);\n+  /* Sixteen levels per channel, without dithering or edge antialiasing. */\n+  return (((c.red+8)/17*17)<<16)|(((c.green+8)/17*17)<<8)|((c.blue+8)/17*17);\n+}\n+\n+static bool grok_mosaic_on_stroke(const struct qpk_polygon_s *p,int x,int y)\n+{\n+  double px=x+1,py=y+1,r=p->stroke>2?p->stroke*0.5:1;\n+  for(unsigned i=0;i<p->count;i++) {\n+    lv_point_precise_t a=p->points[i],b=p->points[(i+1)%p->count];\n+    double dx=b.x-a.x,dy=b.y-a.y,denom=dx*dx+dy*dy;\n+    double t=denom>0?((px-a.x)*dx+(py-a.y)*dy)/denom:0;\n+    if(t<0)t=0;if(t>1)t=1;\n+    double ex=px-a.x-t*dx,ey=py-a.y-t*dy;\n+    if(ex*ex+ey*ey<=r*r)return true;\n+  }\n+  return false;\n+}\n+\n+static void grok_mosaic_draw(lv_layer_t *layer,const struct qpk_polygon_s *p,const lv_area_t *coords)\n+{\n+  if(!p->opacity)return;\n+  const lv_area_t *clip=&layer->_clip_area;\n+  int xmin=clip->x1-coords->x1,xmax=clip->x2-coords->x1;\n+  int ymin=clip->y1-coords->y1,ymax=clip->y2-coords->y1;\n+  int width=coords->x2-coords->x1+1,height=coords->y2-coords->y1+1;\n+  if(xmin<0)xmin=0;if(ymin<0)ymin=0;\n+  if(xmax>=width)xmax=width-1;if(ymax>=height)ymax=height-1;\n+  if(xmin>xmax||ymin>ymax)return;\n+  xmin=xmin/2*2;ymin=ymin/2*2;\n+  lv_draw_rect_dsc_t d;lv_draw_rect_dsc_init(&d);d.radius=0;d.bg_opa=p->opacity;\n+  for(int y=ymin;y<=ymax;y+=2) {\n+    struct {int l,r;} spans[QPK_POLYGON_POINTS];unsigned span_count=0;\n+    if(!p->stroke)for(int dy=0;dy<2;dy++) {\n+      double sample=y+dy+0.5,cuts[QPK_POLYGON_POINTS];unsigned count=0;\n+      for(unsigned i=0;i<p->count;i++) {\n+        lv_point_precise_t a=p->points[i],b=p->points[(i+1)%p->count];\n+        if((a.y<=sample&&b.y>sample)||(b.y<=sample&&a.y>sample)) {\n+          double x=a.x+(sample-a.y)*(b.x-a.x)/(b.y-a.y);\n+          unsigned j=count++;while(j&&cuts[j-1]>x){cuts[j]=cuts[j-1];j--;}cuts[j]=x;\n+        }\n+      }\n+      for(unsigned i=0;i+1<count;i+=2) {\n+        int l=(int)floor(cuts[i]/2)*2,r=(int)ceil(cuts[i+1]/2)*2-2;\n+        if(l<xmin)l=xmin;if(r>xmax)r=xmax/2*2;if(l>r)continue;\n+        /* Two subrows yield at most count/2 * 2 bounded spans. */\n+        unsigned j=span_count++;\n+        while(j&&spans[j-1].l>l){spans[j]=spans[j-1];j--;}\n+        spans[j].l=l;spans[j].r=r;\n+      }\n+    }\n+    /* Merge coverage before compositing, so a translucent ribbon is painted\n+     * once per cell, including overlaps between the two sampled subrows. */\n+    unsigned merged=0;\n+    for(unsigned i=0;i<span_count;i++) {\n+      if(merged&&spans[i].l<=spans[merged-1].r+2){if(spans[i].r>spans[merged-1].r)spans[merged-1].r=spans[i].r;}\n+      else {spans[merged].l=spans[i].l;spans[merged++].r=spans[i].r;}\n+    }\n+    if(p->stroke){spans[0].l=xmin;spans[0].r=xmax;merged=1;}\n+    for(unsigned i=0;i<merged;i++) {\n+      int run=-1;uint32_t previous=0;\n+      for(int x=spans[i].l;x<=spans[i].r+2;x+=2) {\n+        bool covered=x<=spans[i].r&&(!p->stroke||grok_mosaic_on_stroke(p,x,y));\n+        uint32_t color=covered?grok_mosaic_color(p,x,y):0;\n+        if(run>=0&&(!covered||color!=previous)) {\n+          lv_area_t area={coords->x1+run,coords->y1+y,coords->x1+x-1,coords->y1+y+1};\n+          d.bg_color=lv_color_hex(previous);lv_draw_rect(layer,&d,&area);run=-1;\n+        }\n+        if(covered&&run<0){run=x;previous=color;}\n+      }\n+    }\n+  }\n+}\n*** End Patch"));
text(await tools.apply_patch("*** Begin Patch\n*** Add File: [PROJECT_WORKSPACE]/project/tools/generate_grok_mosaic.py\n+#!/usr/bin/env python3\n+\"\"\"Build an isolated pixel-art mini candidate with a per-polygon opt-in.\"\"\"\n+from pathlib import Path\n+import hashlib,json\n+from generate_grok_sizes import replace_once\n+\n+def main():\n+    repo=Path(__file__).resolve().parents[1];root=repo.parent;old=root/'output/grok-sizes';out=root/'output/grok-mosaic';out.mkdir(exist_ok=True)\n+    source=(old/'mini/app.js').read_text(encoding='utf-8')\n+    for call in ['ui.polygonBuffer(points.buffer,c,opa,width,grad)','ui.polygon(points,c,opa,width,grad)',\n+                 'ui.polygonSetBuffer(n.handles[k],points.buffer,c,opa,width,grad)','ui.polygonSet(n.handles[k],points,c,opa,width,grad)']:\n+        source=replace_once(source,call,call[:-1]+',2)')\n+    (out/'app.js').write_text(source,encoding='utf-8')\n+    polygon=(old/'polygon.inc').read_text(encoding='utf-8')\n+    polygon=replace_once(polygon,'unsigned stroke;','unsigned stroke,pixel_cell;')\n+    helper=(repo/'ouo/grok_mosaic_draw.inc').read_text(encoding='utf-8')\n+    polygon=replace_once(polygon,'static void qpk_polygon_draw(lv_event_t *e)',helper+'\\nstatic void qpk_polygon_draw(lv_event_t *e)')\n+    polygon=replace_once(polygon,'lv_layer_t *layer=lv_event_get_layer(e);','lv_layer_t *layer=lv_event_get_layer(e);\\n  if(p->pixel_cell){grok_mosaic_draw(layer,p,&coords);return;}')\n+    polygon=replace_once(polygon,'if(handle&&!qpk_widget_current(handle,generation))',\n+        'int32_t cell=0;\\n  if(argc>offset+5&&!JS_IsUndefined(argv[offset+5])&&JS_ToInt32(c,&cell,argv[offset+5])<0)return JS_EXCEPTION;\\n  if(cell!=0&&cell!=2)return JS_ThrowRangeError(c,\"pixel cell must be 0 or 2\");\\n  if(cell){minx=(int32_t)floor(minx/2.0)*2;miny=(int32_t)floor(miny/2.0)*2;maxx=(int32_t)ceil((maxx+1)/2.0)*2-1;maxy=(int32_t)ceil((maxy+1)/2.0)*2-1;}\\n  if(handle&&!qpk_widget_current(handle,generation))')\n+    polygon=replace_once(polygon,'p->stroke==sw&&','p->stroke==sw&&p->pixel_cell==(unsigned)cell&&')\n+    polygon=replace_once(polygon,'p->opacity=opa;p->stroke=sw;','p->opacity=opa;p->stroke=sw;p->pixel_cell=cell;')\n+    (out/'polygon.inc').write_text(polygon,encoding='utf-8')\n+    tests=(old/'mini/test-app.cjs').read_text(encoding='utf-8')\n+    tests=replace_once(tests,'function polygon(points,color,opacity,width,gradient){','function polygon(points,color,opacity,width,gradient,pixelCell){assert.equal(pixelCell,2);')\n+    (out/'test-app.cjs').write_text(tests,encoding='utf-8')\n+    sources=json.loads((old/'SOURCES.json').read_text())\n+    report={'diameter_px':48,'pixel_cell_px':2,'per_polygon_opt_in':True,'full_effects':True,'flashed':False,'production_applied':False,\n+        'source_sha256':{'app':hashlib.sha256(source.encode()).hexdigest(),'polygon':hashlib.sha256(polygon.encode()).hexdigest()},\n+        'medium_app_sha256':hashlib.sha256((old/'medium/app.js').read_bytes()).hexdigest(),'production_sha256':sources['production_sha256']}\n+    (out/'SOURCES.json').write_text(json.dumps(report,indent=2)+'\\n')\n+    print('GROK_MOSAIC_CANDIDATE_OK',report['source_sha256'])\n+if __name__=='__main__':main()\n*** End Patch"));
