  if (present[1]) lv_obj_set_style_border_color(obj, lv_color_hex(values[1]), 0);
  if (present[2]) lv_obj_set_style_border_width(obj, values[2], 0);
  if (present[3]) lv_obj_set_style_border_opa(obj, values[3], 0);
